import { useEffect, useRef, useState } from 'react';
import type { Pokemon } from '../data/pokemon/schema';
// Generated by scripts/generate-sprites.mjs; the 475px source PNGs are never requested at runtime.
// Matches the CSS boxes: .sprite-small 64px, .sprite-large 112px (96px on narrow screens).
const defaultSizes = { small: '64px', large: '(max-width: 520px) 96px, 112px' } as const;
export default function PokemonSprite({ pokemon, size = 'small', eager = false, sizes = defaultSizes[size] }: { pokemon: Pokemon; size?: 'small' | 'large'; eager?: boolean; sizes?: string }) {
  const [failed, setFailed] = useState(false);
  const image = useRef<HTMLImageElement>(null);
  useEffect(() => {
    // A prefilled image can fail before React attaches its error handler.
    if (image.current?.complete && image.current.naturalWidth === 0) setFailed(true);
  }, [pokemon.number]);
  const number = pokemon.number;
  // CSS fixes every sprite box to a square, so the file only has to cover sizes x device pixel ratio.
  const src = `/sprites/official/160/${number}.webp`;
  const srcSet = `/sprites/official/160/${number}.webp 160w, /sprites/official/320/${number}.webp 320w`;
  return <span className={`pokemon-sprite sprite-${size}`} aria-hidden="true">
    {failed ? <span className="sprite-fallback">#{number}</span> : <img ref={image} key={number} src={src} srcSet={srcSet} sizes={sizes} alt="" width={160} height={160} loading={eager ? 'eager' : 'lazy'} decoding="async" onError={() => setFailed(true)}/>}
  </span>;
}
